/**
 * Scene Image Generator — Generates high-detail 3D Pixar scene keyframe images
 * via Gemini Web before generating videos with Veo.
 *
 * Each scene image is generated by uploading the original character reference image
 * and providing the full scene prompt, detailed props, and character dialogues.
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import axios from "axios";
import { randomUUID } from "crypto";
import { ensureChromeRunning, createBackgroundPage, getFrontmostApp, restoreUserFocus, toHostPath } from "./veoAutomation.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DOWNLOADS_DIR = path.resolve(__dirname, "../data/downloads");
const CHROME_DEBUG_PORT = process.env.CHROME_DEBUG_PORT || "9222";
const GEMINI_URL = "https://gemini.google.com/app";

export interface SceneImageResult {
  sceneIndex: number;
  success: boolean;
  imagePath?: string;
  imageUrl?: string;
  prompt: string;
  error?: string;
  durationMs: number;
}

export interface AllSceneImagesResult {
  success: boolean;
  sceneImagePaths: string[];
  results: SceneImageResult[];
  errors: string[];
  durationMs: number;
}

/**
 * Downloads a remote image URL to a local temporary file for uploading to Gemini.
 */
export async function downloadLocalCopy(imageUrl: string, tempDir: string = DOWNLOADS_DIR): Promise<string | null> {
  if (!imageUrl) return null;
  if (fs.existsSync(imageUrl)) return imageUrl;

  try {
    let fetchUrl = imageUrl;
    if (imageUrl.includes(".amazonaws.com/")) {
      const parts = imageUrl.split(".amazonaws.com/");
      if (parts.length > 1) {
        const key = parts[1];
        const port = process.env.PORT || "3400";
        fetchUrl = `http://127.0.0.1:${port}/api/products/image-proxy?key=${encodeURIComponent(key)}`;
      }
    } else if (imageUrl.startsWith("/")) {
      const port = process.env.PORT || "3400";
      fetchUrl = `http://127.0.0.1:${port}${imageUrl}`;
    }

    const response = await axios.get(fetchUrl, { responseType: "arraybuffer", timeout: 15000 });
    const contentType = String(response.headers["content-type"] ?? "image/jpeg");
    const ext = contentType.split("/")[1] || "jpg";
    const tempFilename = `gemini_ref_${randomUUID().split("-")[0]}.${ext}`;
    const localPath = path.join(tempDir, tempFilename);
    fs.writeFileSync(localPath, response.data);
    return localPath;
  } catch (err: any) {
    console.warn(`⚠️  [SceneImgGen] Failed to download image: ${err.message}`);
    return null;
  }
}

/**
 * Constructs an ultra-detailed prompt in 100% English for Gemini to generate a scene keyframe image
 * with strict character consistency, rich environment details, props, and zero text overlay.
 */
export function buildDetailedSceneImagePrompt(
  scenePrompt: string,
  sceneIndex: number,
  dialogue?: string,
  hasPreviousScene: boolean = false,
  referenceLabel: string = "Scene 1",
  redrawInstructions?: string
): string {
  const refText = referenceLabel.toLowerCase().includes("reference") || referenceLabel.toLowerCase().includes("image")
    ? referenceLabel
    : `${referenceLabel} reference image`;

  let prompt = `Create a premium 3D Pixar animation storyboard sheet featuring 6 sequential action steps arranged in a clean 2x3 grid for Scene ${sceneIndex + 1}, strictly matching the 3D character design from the attached ${refText}:
${scenePrompt}`;

  if (redrawInstructions && redrawInstructions.trim()) {
    prompt += `\n\n═══════════════════════════════════════════════════════
🎯 CRITICAL CHARACTER & VISUAL CONTINUITY DIRECTIVE (FROM DIRECTOR):
Reference Source: Attached ${refText}.
Director Notes: ${redrawInstructions.trim()}
═══════════════════════════════════════════════════════
- STRICT CHARACTER REPLICATION: Clone and strictly maintain the exact 3D character model, facial expressions, fur/skin texture, eyes, species, proportions, and clothing/accessories established in the attached ${refText}!
- Faithfully apply the director's instructions while executing the scene prompt above.`;
  }

  prompt += `\n\nMandatory Visual & Composition Requirements:
- 6 SEQUENTIAL ACTION STEPS (2x3 GRID): Present 6 sequential progression panels arranged in a clean 2x3 grid layout, depicting step-by-step character actions, movements, and key story beats for this scene.
- 100% Character Consistency: Strictly maintain the exact 3D character model, facial anatomy, fur texture, colors, proportions, and clothing/accessories established in the attached ${refText}.
- Narrative Progression: Show clear, dynamic step-by-step action progression, character interactions, and expressive animation poses throughout the 6 panels.
- Cinematic Lighting & Environment: Beautiful volumetric lighting, rich cozy atmosphere, soft warm shadows, depth of field, and vibrant colors.`;

  if (dialogue && dialogue.trim()) {
    prompt += `\n\n═══════════════════════════════════════════════════════
VIETNAMESE DIALOGUE / THOẠI TIẾNG VIỆT (SINGLE FRAME ONLY):
"${dialogue.trim()}"
═══════════════════════════════════════════════════════
- SUBTITLE / DIALOGUE LAYOUT (SINGLE FRAME):
  Place the Vietnamese dialogue text inside EXACTLY ONE single neat, stylish horizontal subtitle banner box along the bottom of the entire storyboard image canvas.
- TEXT REPETITION PREVENTION (CRITICAL):
  * Place this subtitle banner ONLY ONCE along the bottom edge.
  * Do NOT repeat, stamp, or duplicate this text inside each of the 6 individual action panels.
  * The 6 action panels must remain clean 3D art without text clutter or duplicate captions. Only ONE single dialogue box for the whole scene.`;
  } else {
    prompt += `\n- STRICT NEGATIVE INSTRUCTION: Do NOT add any text, subtitles, captions, speech bubbles, letters, or watermarks anywhere on the image. Clean 3D CGI artwork only.`;
  }

  return prompt;
}

/**
 * Generates a single scene keyframe image via Gemini Web automation.
 */
export async function generateSingleSceneImage(
  browser: any,
  scenePrompt: string,
  referenceImagePaths: string | string[],
  sceneIndex: number,
  productSlug: string,
  outputDir: string,
  dialogue?: string,
  referenceLabel: string = "Scene 1",
  redrawInstructions?: string
): Promise<SceneImageResult> {
  const startTime = Date.now();
  let page: any = null;

  try {
    page = await createBackgroundPage(browser);
    console.log(`🎨 [SceneImgGen-Scene ${sceneIndex + 1}] Opened tab for scene image generation...`);

    // Intercept image network responses
    let capturedBlobOrUrl: string | null = null;
    let isPromptSubmitted = false;

    page.on("response", async (response: any) => {
      if (!isPromptSubmitted) return;
      const url = response.url();
      const ct = response.headers()["content-type"] || "";
      if (
        ct.includes("image/") &&
        (url.includes("googleusercontent") || url.includes("aiusercontent") || url.includes("lh3.googleusercontent"))
      ) {
        if (!capturedBlobOrUrl) {
          capturedBlobOrUrl = url;
          console.log(`📸 [SceneImgGen-Scene ${sceneIndex + 1}] Intercepted generated image URL: ${url.slice(0, 80)}...`);
        }
      }
    });

    await page.goto(GEMINI_URL, { waitUntil: "networkidle2", timeout: 60000 });

    // 1. Click "New chat" to isolate context
    try {
      await page.evaluate(() => {
        const btn = (document.querySelector('[data-test-id="new-chat-button"]') as HTMLElement) ||
          (Array.from(document.querySelectorAll("a, button, [role='button']")).find((el) => {
            const text = (el.textContent || "").toLowerCase();
            return (
              text.includes("new chat") ||
              text.includes("cuộc trò chuyện mới") ||
              text.includes("trò chuyện mới")
            );
          }) as HTMLElement);
        if (btn) btn.click();
      });
      await new Promise((r) => setTimeout(r, 2000));
    } catch {}

    const inputSelector = 'rich-textarea [contenteditable="true"], textarea, [contenteditable="true"]';
    await page.waitForSelector(inputSelector, { timeout: 30000 });

    // 2. Upload reference image(s) (original reference image + previous scene for continuity)
    const pathsToUpload: string[] = Array.isArray(referenceImagePaths)
      ? referenceImagePaths.filter((p) => p && fs.existsSync(p))
      : (referenceImagePaths && fs.existsSync(referenceImagePaths) ? [referenceImagePaths] : []);

    if (pathsToUpload.length > 0) {
      const prevApp = getFrontmostApp();
      console.log(`📤 [SceneImgGen-Scene ${sceneIndex + 1}] Uploading ${pathsToUpload.length} reference image(s) for character & visual continuity...`);
      try {
        // Click upload button (+)
        await page.evaluate(() => {
          const btn =
            (document.querySelector('button[aria-label*="Nội dung tải lên"]') as HTMLButtonElement) ||
            (document.querySelector('button[aria-label*="Upload"]') as HTMLButtonElement) ||
            (document.querySelector('button[aria-label*="công cụ"]') as HTMLButtonElement) ||
            (Array.from(document.querySelectorAll("button")).find(
              (b) =>
                b.innerHTML.includes("plus") ||
                b.getAttribute("aria-label")?.includes("Nội dung tải lên") ||
                b.getAttribute("aria-label")?.includes("Upload")
            ) as HTMLButtonElement);
          if (btn) {
            btn.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, view: window }));
          }
        });
        restoreUserFocus(prevApp);
        await new Promise((r) => setTimeout(r, 1200));

        // Click "Tải lên từ máy tính" / "Upload from computer"
        await page.evaluate(() => {
          const container = document.querySelector(".cdk-overlay-container") || document;
          const items = Array.from(container.querySelectorAll("button, [role='menuitem'], .mat-mdc-menu-item, span, div"));
          const uploadItem = items.find((el) => {
            const text = el.textContent?.trim() || "";
            return (
              text === "Tải lên từ máy tính" ||
              text === "Upload from computer" ||
              text === "Tải lên từ thiết bị" ||
              text === "Upload from device" ||
              text === "Tải lên" ||
              text.includes("máy tính") ||
              text.includes("computer")
            );
          }) as HTMLElement;
          if (uploadItem) {
            uploadItem.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, view: window }));
          }
        });
        restoreUserFocus(prevApp);
        await new Promise((r) => setTimeout(r, 1200));

        // Wait for file input and upload all reference files
        const fileInput = await page.waitForSelector('input[type="file"]', { timeout: 10000 });
        if (fileInput) {
          const hostPaths = pathsToUpload.map(toHostPath);
          await (fileInput as any).uploadFile(...hostPaths);
          restoreUserFocus(prevApp);
          console.log(`✅ [SceneImgGen-Scene ${sceneIndex + 1}] Attached ${pathsToUpload.length} image(s). Waiting 4.5s for thumbnail preview...`);
          await new Promise((r) => setTimeout(r, 4500));
        }
      } catch (uploadErr: any) {
        console.warn(`⚠️  [SceneImgGen-Scene ${sceneIndex + 1}] Upload failed: ${uploadErr.message}`);
      } finally {
        restoreUserFocus(prevApp);
      }
    }

    // 3. Inject detailed prompt
    let cleanScenePrompt = scenePrompt;
    let dialogueToUse = dialogue;
    if (/THOẠI TIẾNG VIỆT:/i.test(scenePrompt)) {
      const parts = scenePrompt.split(/THOẠI TIẾNG VIỆT:/i);
      cleanScenePrompt = parts[0].trim();
      if (!dialogueToUse || !dialogueToUse.trim()) {
        dialogueToUse = parts[1].trim();
      }
    }

    const hasPreviousScene = pathsToUpload.length > 1 || sceneIndex > 0 || Boolean(referenceLabel && referenceLabel !== "Scene 1");
    const fullPrompt = buildDetailedSceneImagePrompt(
      cleanScenePrompt,
      sceneIndex,
      dialogueToUse,
      hasPreviousScene,
      referenceLabel,
      redrawInstructions
    );
    const prevAppTyping = getFrontmostApp();
    console.log(`✏️  [SceneImgGen-Scene ${sceneIndex + 1}] Typing detailed scene prompt (Ref: ${referenceLabel || "Auto"}${redrawInstructions ? ` | Note: "${redrawInstructions.slice(0, 50)}..."` : ""})...`);

    await page.evaluate((sel: string, text: string) => {
      const el = document.querySelector(sel) as HTMLElement;
      if (el) {
        el.focus();
        el.innerText = text;
        el.dispatchEvent(new Event("input", { bubbles: true }));
        el.dispatchEvent(new Event("change", { bubbles: true }));
      }
    }, inputSelector, fullPrompt);
    restoreUserFocus(prevAppTyping);

    // Record existing generated images BEFORE submitting prompt to reliably detect the new image
    const initialGeneratedCount = await page.evaluate(() => {
      const imgs = Array.from(
        document.querySelectorAll("button.image-button img, single-image img, generated-image img")
      ) as HTMLImageElement[];
      return imgs.filter(
        (img) =>
          !img.closest("user-query, .user-query, rich-textarea, uploader-file, .file-preview") &&
          img.naturalWidth > 200
      ).length;
    });
    console.log(`📊 [SceneImgGen-Scene ${sceneIndex + 1}] Existing model generated images before submit: ${initialGeneratedCount}`);

    // 4. Click Send / Generate
    await page.evaluate(() => {
      const selectors = [
        'button[aria-label="Gửi tin nhắn"]',
        'button[aria-label*="Gửi" i]',
        'button[aria-label*="Send" i]',
        'button.send-button',
        'mat-icon[fonticon="arrow_upward"]',
        'button mat-icon[data-mat-icon-name="arrow_upward"]',
      ];
      for (const sel of selectors) {
        const btn = document.querySelector(sel) as HTMLButtonElement;
        if (btn && !btn.disabled) {
          btn.click();
          return;
        }
      }
      const btns = Array.from(document.querySelectorAll("button"));
      const sendBtn = btns.find(
        (b) =>
          b.getAttribute("aria-label")?.toLowerCase().includes("gửi") ||
          b.innerHTML.includes("send") ||
          b.innerHTML.includes("arrow_upward")
      );
      if (sendBtn) sendBtn.click();
    });

    isPromptSubmitted = true;
    console.log(`📤 [SceneImgGen-Scene ${sceneIndex + 1}] Prompt submitted! Waiting for Gemini to render new 3D scene...`);

    // 5. Poll for NEW generated image in DOM (up to 90 seconds)
    const pollStart = Date.now();
    const MAX_WAIT_MS = 90000;
    let targetImageSrc: string | null = null;

    // Wait at least 6s before polling to allow Gemini to acknowledge prompt and start generation
    await new Promise((r) => setTimeout(r, 6000));

    while (Date.now() - pollStart < MAX_WAIT_MS) {
      await new Promise((r) => setTimeout(r, 3000));
      const elapsed = Math.round((Date.now() - pollStart) / 1000);

      const check = await page.evaluate((initialCount: number) => {
        // STRICTLY find generated images inside model responses
        const allCandidates = Array.from(
          document.querySelectorAll("button.image-button img, single-image img, generated-image img")
        ) as HTMLImageElement[];

        // Filter out any image that is part of the user input or file attachment
        const valid = allCandidates.filter((img) => {
          if (img.closest("user-query, .user-query, rich-textarea, uploader-file, .file-preview")) {
            return false;
          }
          const hasValidSrc =
            img.src &&
            (img.src.startsWith("blob:") ||
              img.src.includes("googleusercontent") ||
              img.src.includes("aiusercontent"));
          const isLargeEnough = (img.naturalWidth > 250 || img.width > 250) && (img.naturalHeight > 200 || img.height > 200);
          const isReady = img.classList.contains("loaded") || img.complete;
          return hasValidSrc && isLargeEnough && isReady;
        });

        // Condition A: A new generated image appeared in the model response
        if (valid.length > initialCount) {
          const latestImg = valid[valid.length - 1];
          return {
            found: true,
            src: latestImg.src,
            width: latestImg.naturalWidth || latestImg.width,
            height: latestImg.naturalHeight || latestImg.height,
            count: valid.length,
          };
        }

        // Condition B: Full size download button appeared
        const dlBtns = Array.from(document.querySelectorAll("button")).filter((b) => {
          const a = (b.getAttribute("aria-label") || "").toLowerCase();
          return a.includes("kích thước đầy đủ") || a.includes("full size");
        });
        if (dlBtns.length > initialCount && valid.length > 0) {
          const latestImg = valid[valid.length - 1];
          return {
            found: true,
            src: latestImg.src,
            width: latestImg.naturalWidth || latestImg.width,
            height: latestImg.naturalHeight || latestImg.height,
            count: valid.length,
          };
        }

        return { found: false, src: null, count: valid.length };
      }, initialGeneratedCount);

      if (check.found && check.src) {
        targetImageSrc = check.src;
        console.log(`🎯 [SceneImgGen-Scene ${sceneIndex + 1}] New AI generated image ready at ${elapsed}s! (${check.width}x${check.height}px, total ${check.count})`);
        break;
      }

      console.log(`⏳ [SceneImgGen-Scene ${sceneIndex + 1}] Gemini is generating scene image... (${elapsed}s)`);
    }

    if (!targetImageSrc) {
      throw new Error(`Timeout waiting for scene image ${sceneIndex + 1} from Gemini`);
    }

    // 6. Download and save the image locally (extracting via Canvas / Element Screenshot / HTTP)
    const targetFilename = `scene_${sceneIndex + 1}.png`;
    const targetPath = path.join(outputDir, targetFilename);

    console.log(`📦 [SceneImgGen-Scene ${sceneIndex + 1}] Extracting generated image to ${targetFilename}...`);
    let imageSaved = false;

    // Method 1: HTML5 Canvas extraction from the model's generated image element
    try {
      const base64Data = await page.evaluate((targetSrc: string) => {
        const allCandidates = Array.from(
          document.querySelectorAll("button.image-button img, single-image img, generated-image img")
        ) as HTMLImageElement[];

        const valid = allCandidates.filter((img) => {
          return (
            !img.closest("user-query, .user-query, rich-textarea, uploader-file, .file-preview") &&
            (img.naturalWidth > 250 || img.width > 250)
          );
        });

        const targetImg = (targetSrc ? valid.find((i) => i.src === targetSrc) : null) || valid[valid.length - 1];
        if (!targetImg) return null;

        const canvas = document.createElement("canvas");
        canvas.width = targetImg.naturalWidth || targetImg.width;
        canvas.height = targetImg.naturalHeight || targetImg.height;
        const ctx = canvas.getContext("2d");
        if (!ctx) return null;
        ctx.drawImage(targetImg, 0, 0);
        return canvas.toDataURL("image/png").replace(/^data:image\/png;base64,/, "");
      }, targetImageSrc);

      if (base64Data && base64Data.length > 1000) {
        fs.writeFileSync(targetPath, Buffer.from(base64Data, "base64"));
        imageSaved = true;
        console.log(`✅ [SceneImgGen-Scene ${sceneIndex + 1}] Successfully extracted image via Canvas (${Math.round(base64Data.length * 0.75 / 1024)} KB)`);
      }
    } catch (canvasErr: any) {
      console.warn(`⚠️  [SceneImgGen-Scene ${sceneIndex + 1}] Canvas extraction failed: ${canvasErr.message}`);
    }

    // Method 2: Puppeteer Element Screenshot fallback directly from generated-image element
    if (!imageSaved) {
      try {
        const imgHandles = await page.$$("generated-image img, single-image img, button.image-button img");
        if (imgHandles.length > 0) {
          const lastHandle = imgHandles[imgHandles.length - 1];
          const buf = await lastHandle.screenshot({ type: "png" });
          if (buf && buf.length > 5000) {
            fs.writeFileSync(targetPath, buf);
            imageSaved = true;
            console.log(`✅ [SceneImgGen-Scene ${sceneIndex + 1}] Extracted image via element screenshot (${Math.round(buf.length / 1024)} KB)`);
          }
        }
      } catch (screenErr: any) {
        console.warn(`⚠️  [SceneImgGen-Scene ${sceneIndex + 1}] Element screenshot failed: ${screenErr.message}`);
      }
    }

    // Method 3: HTTP Axios Download fallback (if public URL)
    if (!imageSaved && targetImageSrc.startsWith("http") && !targetImageSrc.startsWith("blob:")) {
      try {
        const response = await axios.get(targetImageSrc, { responseType: "arraybuffer", timeout: 20000 });
        fs.writeFileSync(targetPath, response.data);
        imageSaved = true;
        console.log(`✅ [SceneImgGen-Scene ${sceneIndex + 1}] Downloaded image via Axios`);
      } catch (httpErr: any) {
        console.warn(`⚠️  [SceneImgGen-Scene ${sceneIndex + 1}] Axios download failed: ${httpErr.message}`);
      }
    }

    if (!imageSaved || !fs.existsSync(targetPath)) {
      throw new Error(`Failed to extract or save scene image ${sceneIndex + 1} from Gemini`);
    }

    console.log(`✅ [SceneImgGen-Scene ${sceneIndex + 1}] Saved scene image: ${targetPath}`);
    const durationMs = Date.now() - startTime;

    return {
      sceneIndex,
      success: true,
      imagePath: targetPath,
      imageUrl: targetImageSrc,
      prompt: fullPrompt,
      durationMs,
    };
  } catch (err: any) {
    console.error(`❌ [SceneImgGen-Scene ${sceneIndex + 1}] Error: ${err.message}`);
    const durationMs = Date.now() - startTime;
    return {
      sceneIndex,
      success: false,
      prompt: scenePrompt,
      error: err.message,
      durationMs,
    };
  } finally {
    if (page) await page.close().catch(() => {});
  }
}

/**
 * Generates all 6 scene keyframe images sequentially with Gemini.
 * Once all 6 images are generated, returns their paths so Veo can use them.
 */
export async function generateAllSceneImages(
  prompts: string[],
  originalImageUrl: string,
  productSlug: string = "video",
  customOutputDir?: string,
  dialogues?: string[]
): Promise<AllSceneImagesResult> {
  const startTime = Date.now();
  const outputDir = customOutputDir || DOWNLOADS_DIR;
  if (!fs.existsSync(outputDir)) fs.mkdirSync(outputDir, { recursive: true });

  console.log(`\n${"═".repeat(60)}`);
  console.log(`🎨 [SceneImgGen] Starting Generation of ${prompts.length} Scene Images via Gemini...`);
  console.log(`   Reference Image: ${originalImageUrl}`);
  console.log(`   Target Directory: ${outputDir}`);
  console.log(`${"═".repeat(60)}\n`);

  // Download reference image to local path
  const localRefImage = await downloadLocalCopy(originalImageUrl, outputDir);
  if (!localRefImage || !fs.existsSync(localRefImage)) {
    console.warn(`⚠️  [SceneImgGen] Could not download reference image: ${originalImageUrl}`);
  }

  let browser: any = null;
  let ownsBrowser = false;

  try {
    let puppeteer: any;
    try {
      puppeteer = (await import("puppeteer")).default;
    } catch {
      throw new Error("puppeteer is not installed.");
    }

    await ensureChromeRunning();

    try {
      browser = await puppeteer.connect({
        browserURL: `http://127.0.0.1:${CHROME_DEBUG_PORT}`,
        defaultViewport: null,
      });
      ownsBrowser = false;
      console.log(`✅ [SceneImgGen] Connected to running Chrome session on port ${CHROME_DEBUG_PORT}`);
    } catch (connectErr: any) {
      throw new Error(`Cannot connect to Chrome on port ${CHROME_DEBUG_PORT}: ${connectErr.message}`);
    }

    const results: SceneImageResult[] = [];
    const sceneImagePaths: string[] = [];
    const errors: string[] = [];

    for (let i = 0; i < prompts.length; i++) {
      console.log(`\n🖼️  [SceneImgGen] Generating Scene ${i + 1}/${prompts.length}...`);
      const dialogueText = dialogues && dialogues[i] ? dialogues[i] : undefined;

      // Master Structure & Character Anchoring:
      // - Phân cảnh 1 (i = 0): Tạo từ ảnh nhân vật gốc ban đầu.
      // - Từ phân cảnh 2 trở đi (i >= 1): Lấy chính ảnh 3D đã tạo từ Phân cảnh 1 (sceneImagePaths[0])
      //   làm hình mẫu chuẩn về cấu trúc, tạo hình, tỉ lệ và chất liệu cho các phân cảnh sau!
      const refImages: string[] = [];
      if (i === 0) {
        if (localRefImage && fs.existsSync(localRefImage)) {
          refImages.push(localRefImage);
        } else if (originalImageUrl) {
          refImages.push(originalImageUrl);
        }
      } else {
        // Từ phân cảnh 2 trở đi: CHỈ upload hình tạo từ phân cảnh 1, KHÔNG upload lại ảnh gốc
        const scene1Image = sceneImagePaths[0];
        if (scene1Image && fs.existsSync(scene1Image)) {
          refImages.push(scene1Image);
          console.log(`🎯 [SceneImgGen] Scene ${i + 1} CHỈ upload ảnh tạo Phân cảnh 1 làm mẫu: ${path.basename(scene1Image)} (không up lại ảnh gốc)`);
        } else if (localRefImage && fs.existsSync(localRefImage)) {
          refImages.push(localRefImage);
        }
      }

      const res = await generateSingleSceneImage(
        browser,
        prompts[i],
        refImages.length > 0 ? refImages : (localRefImage || originalImageUrl),
        i,
        productSlug,
        outputDir,
        dialogueText
      );

      results.push(res);
      if (res.success && res.imagePath) {
        sceneImagePaths.push(res.imagePath);
      } else {
        errors.push(`Scene ${i + 1}: ${res.error || "Failed to generate"}`);
      }

      // Short delay between image generation requests to respect account pacing
      if (i < prompts.length - 1) {
        const delayMs = 3000;
        console.log(`⏳ [SceneImgGen] Pacing delay ${delayMs}ms before next scene...`);
        await new Promise((r) => setTimeout(r, delayMs));
      }
    }

    const durationMs = Date.now() - startTime;
    console.log(`\n🎉 [SceneImgGen] Completed ${sceneImagePaths.length}/${prompts.length} scene images in ${(durationMs / 1000).toFixed(1)}s!`);

    return {
      success: sceneImagePaths.length > 0,
      sceneImagePaths,
      results,
      errors,
      durationMs,
    };
  } finally {
    if (browser) {
      try {
        browser.disconnect?.();
      } catch {}
    }
  }
}

/**
 * Generates a single scene image on-demand and connects/disconnects Chrome cleanly.
 * Ideal for progressive UI rendering scene-by-scene without long HTTP timeouts.
 */
export async function generateSingleSceneImageStandalone(
  scenePrompt: string,
  originalImageUrl: string,
  sceneIndex: number,
  productSlug: string = "scene",
  customOutputDir?: string,
  dialogue?: string,
  scene1ImagePath?: string,
  customReferencePath?: string,
  referenceLabel?: string,
  redrawInstructions?: string
): Promise<SceneImageResult> {
  const outputDir = customOutputDir || DOWNLOADS_DIR;
  if (!fs.existsSync(outputDir)) fs.mkdirSync(outputDir, { recursive: true });

  const localRefImage = await downloadLocalCopy(originalImageUrl, outputDir);

  let browser: any = null;
  try {
    let puppeteer: any;
    try {
      puppeteer = (await import("puppeteer")).default;
    } catch {
      throw new Error("puppeteer is not installed.");
    }

    await ensureChromeRunning();
    browser = await puppeteer.connect({
      browserURL: `http://127.0.0.1:${CHROME_DEBUG_PORT}`,
      defaultViewport: null,
    });

    const refImages: string[] = [];
    let activeRefLabel = referenceLabel || `Scene 1`;

    if (customReferencePath && fs.existsSync(customReferencePath)) {
      refImages.push(customReferencePath);
      activeRefLabel = referenceLabel || `Reference Image`;
      console.log(`🎯 [SceneImgGen-Scene ${sceneIndex + 1}] Dùng ảnh tham khảo chỉ định: ${path.basename(customReferencePath)} (${activeRefLabel})`);
    } else if (sceneIndex === 0) {
      if (localRefImage && fs.existsSync(localRefImage)) {
        refImages.push(localRefImage);
      } else if (originalImageUrl) {
        refImages.push(originalImageUrl);
      }
      activeRefLabel = referenceLabel || "Original Reference";
    } else {
      if (scene1ImagePath && fs.existsSync(scene1ImagePath)) {
        refImages.push(scene1ImagePath);
        console.log(`🎯 [SceneImgGen-Scene ${sceneIndex + 1}] Upload ảnh tạo Phân cảnh 1 làm mẫu: ${path.basename(scene1ImagePath)}`);
      } else if (localRefImage && fs.existsSync(localRefImage)) {
        refImages.push(localRefImage);
      }
    }

    return await generateSingleSceneImage(
      browser,
      scenePrompt,
      refImages.length > 0 ? refImages : (localRefImage || originalImageUrl),
      sceneIndex,
      productSlug,
      outputDir,
      dialogue,
      activeRefLabel,
      redrawInstructions
    );
  } finally {
    if (browser) {
      try {
        browser.disconnect?.();
      } catch {}
    }
  }
}

